#include "../RahiTuber/MaxFaceLayer.h"
#include <iostream>
#include <stdexcept>
#include <vector>
struct P{float x,y;};
static std::vector<unsigned char> field(float height){std::vector<P> polygon{{60,96},{88,96-height},{168,96-height},{196,96},{168,96+height},{88,96+height}};std::vector<unsigned char> pixels(256*192*4,255);
 for(int y=0;y<192;++y)for(int x=0;x<256;++x){float px=x+.5f,py=y+.5f,d=1000;bool inside=false;for(int i=0;i<6;++i){auto a=polygon[i],b=polygon[(i+1)%6];float dx=b.x-a.x,dy=b.y-a.y,t=std::clamp(((px-a.x)*dx+(py-a.y)*dy)/(dx*dx+dy*dy),0.f,1.f);d=std::min(d,std::hypot(px-a.x-t*dx,py-a.y-t*dy));if((a.y>py)!=(b.y>py)&&px<(b.x-a.x)*(py-a.y)/(b.y-a.y)+a.x)inside=!inside;}int value=int((std::clamp(inside?d:-d,-32.f,32.f)+32)*255/64+.5f);for(int k=0;k<3;++k)pixels[(y*256+x)*4+k]=value;}return pixels;}
static void check(bool good,const char* msg){if(!good)throw std::runtime_error(msg);}
int main(){sf::Image source;source.create(256,192,{200,70,100,255});sf::Texture video,contour;video.loadFromImage(source);video.setSmooth(true);contour.create(256,192);contour.setSmooth(true);sf::RenderTexture target;check(target.create(256,192),"Target failed");MaxFaceLayer config;config.mask=3;config.zoom=1;config.precisionPadding=0;config.precisionFeather=1;
 auto draw=[&](float height){auto values=field(height);contour.update(values.data());target.clear(sf::Color::Transparent);MaxFaceDraw(target,video,config,{128,96,256,192},false,&contour);target.display();auto image=target.getTexture().copyToImage();long long sum=0;for(int y=0;y<192;++y)for(int x=0;x<256;++x)sum+=image.getPixel(x,y).a;return std::make_pair(image,sum);};
 auto opened=draw(20);check(opened.first.getPixel(128,96).a>250&&opened.first.getPixel(128,55).a==0,"Precise mask includes surrounding skin or cuts mouth interior");auto closed=draw(2);check(closed.second<opened.second/4,"Blink/closed mouth did not narrow its mask");config.precisionPadding=3;auto padded=draw(2);check(padded.second>closed.second,"Eyelid padding failed");config.precisionPadding=.7f;config.zoom=2;config.panX=.035f;config.cropRotation=20;config.precisionOffsetY=2;config.precisionScaleY=1.1f;
 auto adjusted=draw(20);auto values=field(20);auto cpu=MaxFacePixels(source.getPixelsPtr(),256,192,config,256,192,values.data(),256,192);for(int y=0;y<192;++y)for(int x=0;x<256;++x){auto i=(y*256+x)*4;check(std::abs(int(adjusted.first.getPixel(x,y).a)-int(cpu[i+3]))<=4,"GPU contour lost alignment with zoom/pan/rotation or CPU mask");}
 auto oldHeight=config.height,oldRotation=config.rotation;MaxFaceLayer copy;copy.height=.2f;copy.rotation=17;MaxCopyFaceSettings(copy,config);check(copy.precisionPadding==config.precisionPadding&&copy.precisionScaleY==config.precisionScaleY&&copy.height==.2f&&copy.rotation==17,"Precise settings copy failed");
 sf::Image sheet;sheet.create(256*3,192,{20,30,45});sheet.copy(opened.first,0,0);sheet.copy(closed.first,256,0);sheet.copy(padded.first,512,0);sheet.saveToFile("precise-face-render-check.png");std::cout<<"PASS: precise eyelid/lip contour, mouth interior, blink response, padding, transformed GPU/CPU agreement and settings copy\n";}
